mapper.update:
UPDATE crm_messenger_message
SET status = #{status}
WHERE tenant_id = #{tenantId} AND message_id = #{messageId}

UPDATE crm_messenger_message
SET status = 'read'
WHERE tenant_id = #{tenantId}
  AND psid = #{psid}
  AND direction = 1
  AND send_time IS NOT NULL
  AND send_time <= #{watermark}
  AND (status IS NULL OR LOWER(status) <> 'read')

mapper.select:
SELECT id, tenant_id, conversation_id, psid, message_id, message_type,
       content, direction, send_time, status,
       media_id, media_url, media_mime_type, filename, raw_json, source,
       create_time
FROM crm_messenger_message
WHERE conversation_id = #{conversationId}

    AND id < #{beforeMsgId}

ORDER BY send_time DESC, id DESC
LIMIT #{pageSize}

SELECT COUNT(1)
FROM crm_messenger_message
WHERE tenant_id = #{tenantId}

    AND direction = #{direction}


    AND send_time >= #{startTime}


    AND send_time <= #{endTime}
